import{_ as r,l as i,o as e,c as n,v as o,p as u,x as t,d as s,i as d,S as c}from"./chunks/framework.InCnrqk-.js";const b=JSON.parse('{"title":"Foucault 限价簿竞争","description":"","frontmatter":{"title":"Foucault 限价簿竞争","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/foucault-lob.md","filePath":"quant/foucault-lob.md","lastUpdated":1789023840000}'),p={name:"quant/foucault-lob.md"};function h(m,a,E,f,B,_){const l=i("Mermaid");return e(),n("div",null,[a[1]||(a[1]=o('<h1 id="foucault-限价簿竞争" tabindex="-1">Foucault 限价簿竞争 <a class="header-anchor" href="#foucault-限价簿竞争" aria-label="Permalink to &quot;Foucault 限价簿竞争&quot;">​</a></h1><div class="epigraph"><p>挂限价单是出售免费期权：你在等待成交的同时，价值可能走掉，期权被知情者或公开新闻「捡走」。价差必须补偿这份被捡便宜的风险，而不仅补偿排队。</p><footer>—— Foucault, Order flow composition and trading costs in a dynamic limit order market, Journal of Financial Markets, 1999</footer></div><p><a href="/quant/parlour-lob">Parlour</a>让执行概率随队深下降，主摩擦是轮不到你。缺口是对称的另一风险：你排到了，但成交发生在价值已经对你不利之后。Copeland 与 Galai（1983）把做市报价写成被知情者捡走的期权；Foucault（1999）把它放进动态限价簿：交易者在限价与市价之间选择，均衡价差补偿 picking-off。本课不重推队列马尔可夫的状态转移。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>限价单在成交前可被公共信息或知情市价单击中。若价值向上跳而你的卖限价还挂着，你被买走，相当于把低价卖给已经知道该买的人。等待越久、波动越大、信息事件越密，这份期权越贵。交易者比较：(i) 市价，立刻付价差；(ii) 限价，省价差但承担非执行与被捡。问题是均衡里限价单比例、价差与波动如何一起决定，而不把专家当作外生供给。</p><p>Parlour 的深度回复在此仍然在，但驱动价差宽度的主要是被捡风险，不是处理成本。这与 Glosten-Milgrom 的价差同族（逆向选择），实现场所换成了限价簿竞争。</p><h3 id="耐心与即期需求" tabindex="-1">耐心与即期需求 <a class="header-anchor" href="#耐心与即期需求" aria-label="Permalink to &quot;耐心与即期需求&quot;">​</a></h3><p>Foucault 让交易者带不同的等待成本。高等待成本者更常吃市价，成为流动性需求；低等待成本者挂限价，成为供给。组成内生：价差宽时更多人愿意挂，价差窄时更多人吃——与 Parlour 的队列反馈一起，给出限价比例随状态变化。Admati–Pfleiderer 的择时在这里变成「挂还是吃」的静态权衡，时钟可以仍是平稳的。</p><p><span class="marginnote">Foucault, Kadan, Kandel（2005）进一步把簿写成流动性市场，强调执行等待时间。1999 年文章已足够本课：组成与被捡。等待时间的连续化留给 Roşu。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>每期随机到达一个交易者，观测当前价差（或 BBO）与自己的估值、等待成本，选择市价或限价（限价通常放在优于或等于当前最优的一个网格上）。价值服从随机游走或带跳的公共信息。均衡是平稳策略：给定状态，限价与市价的概率使做市期望利润（价差收入减去被捡损失）与执行概率一致。</p><p>比较静态：波动 \\(\\sigma\\) 上升，被捡风险上升，均衡价差加宽，市价单比例可能上升（因为限价更贵）。到达率上升，等待缩短，被捡窗口变窄，价差可以下降。这与「成交越密越流动」的直觉一致，机制是期权时间价值，不是外生 \\(\\sigma_u\\)。</p><h3 id="从期权到价差" tabindex="-1">从期权到价差 <a class="header-anchor" href="#从期权到价差" aria-label="Permalink to &quot;从期权到价差&quot;">​</a></h3><p>Copeland–Galai 的专家必须始终挂出被捡期权。限价簿上这份期权由自愿挂单者分散持有，谁挂谁收权利金（价差），谁也可以选择不挂。供给弹性因此比单一专家大：波动冲击下价差跳开、深度暂时变薄，但不需要一个垄断专家加价。</p>',14)),(e(),u(c,null,{default:t(()=>[d(l,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20LR%0A%20%20Vol%5B%22%E4%BB%B7%E5%80%BC%E6%B3%A2%E5%8A%A8%20%2F%20%E4%BF%A1%E6%81%AF%E8%B7%B3%22%5D%20--%3E%20Opt%5B%22%E9%99%90%E4%BB%B7%20%3D%20%E8%A2%AB%E6%8D%A1%E6%9C%9F%E6%9D%83%22%5D%0A%20%20Wait%5B%22%E7%AD%89%E5%BE%85%E6%88%90%E6%9C%AC%E5%BC%82%E8%B4%A8%22%5D%20--%3E%20Mix%5B%22%E5%B8%82%E4%BB%B7%20vs%20%E9%99%90%E4%BB%B7%22%5D%0A%20%20Opt%20--%3E%20S%5B%22%E5%9D%87%E8%A1%A1%E4%BB%B7%E5%B7%AE%22%5D%0A%20%20Mix%20--%3E%20S%0A%20%20S%20--%3E%20Mix%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>价差是权利金。权利金高，愿意做期权卖方的人多，簿厚；权利金低，只剩最有耐心的人挂着，簿薄、被捡后补给慢。公共新闻到达的瞬间，未及撤单的限价被扫，这就是后文速度竞赛的慢版本：在 1999 年模型里「快」体现在谁先到达下一期，还没有连续时间的抢先。</p><p>与 Easley–O&#39;Hara 事件不确定对照：有事件的日子被捡概率高，限价供给应撤退，价差宽——与事件后验升时 Glosten-Milgrom 价差宽同方向，但供给侧是挂单者退出而不是专家改条件期望。经验上两者纠缠。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>网格粗糙、常无多档深度选择、撤单往往被简化。真实 HFT 把被捡窗口从「下一期」压到微秒，模型的等待成本参数不能直接校准。逆向选择若来自长期内幕而非公共跳，限价期权的希腊值不同，Back 的平滑释放不会表现为一次性扫簿。tick 约束会把价差钉在一档，比较静态失效，见价格栅格课。</p><p><span class="marginnote">不要把「波动升、价差升」只写成 Foucault。库存风险（Ho–Stoll）与事件不确定给出同号预测。识别需要看随后中点是否永久移动（信息）还是回复（库存 / 补给）。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Foucault（1999）把限价单写成被捡便宜的期权，价差补偿 picking-off，下单组成由等待成本内生。</li><li>波动与信息跳加宽价差、改变市价/限价比例；到达率提高可缩短被捡窗口。</li><li>相对 Parlour：主摩擦从「排不到」变成「排到了但价值已走」。</li><li>出处：Foucault, <em>Journal of Financial Markets</em>, 1999；期权直觉见 Copeland and Galai, <em>Journal of Finance</em>, 1983。</li></ul>',8))])}const q=r(p,[["render",h]]);export{b as __pageData,q as default};
